<?php
declare(strict_types=1);require_once __DIR__.'/assets/php/bootstrap.php';$userId=require_login();$db=db();$error=null;
$addressQuery=$db->prepare('SELECT id_direccion,etiqueta,direccion,es_principal FROM direccion_usuario WHERE usr_id=:id ORDER BY es_principal DESC,fecha_creacion DESC');$addressQuery->execute(['id'=>$userId]);$addresses=$addressQuery->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!valid_csrf())throw new RuntimeException('La sesión del formulario venció.');$addressId=filter_input(INPUT_POST,'address_id',FILTER_VALIDATE_INT)?:0;$address='';if($addressId){$s=$db->prepare('SELECT direccion FROM direccion_usuario WHERE id_direccion=:address AND usr_id=:user');$s->execute(['address'=>$addressId,'user'=>$userId]);$address=(string)$s->fetchColumn();}else $address=trim((string)($_POST['new_address']??''));if($address===''||mb_strlen($address)>255)throw new RuntimeException('Selecciona o escribe una dirección de envío válida.');$db->beginTransaction();$items=cart_items_for_user($db,$userId,true);if(!$items)throw new RuntimeException('Tu carrito está vacío.');$subtotal=0.;foreach($items as $item){if(!$item['activo']||(int)$item['stock']<(int)$item['cantidad'])throw new RuntimeException('Uno de los productos ya no tiene existencias suficientes.');$subtotal+=(float)$item['precio']*(int)$item['cantidad'];}$shipping=99.;$total=$subtotal+$shipping;$db->prepare("INSERT INTO pedido (usr_id,estado,total,subtotal,envio,descuento,impuestos,direccion_envio) VALUES (:user,'pendiente',:total,:subtotal,:shipping,0,0,:address)")->execute(['user'=>$userId,'total'=>$total,'subtotal'=>$subtotal,'shipping'=>$shipping,'address'=>$address]);$orderId=(int)$db->lastInsertId();$detail=$db->prepare('INSERT INTO pedido_detalle (pedido_id,producto_id,nombre_producto,cantidad,precio_unitario) VALUES (:order,:product,:name,:quantity,:price)');foreach($items as $item)$detail->execute(['order'=>$orderId,'product'=>$item['producto_id'],'name'=>$item['nombre'],'quantity'=>$item['cantidad'],'price'=>$item['precio']]);$db->prepare('DELETE FROM carrito_item WHERE usr_id=:user')->execute(['user'=>$userId]);$db->commit();redirect('pago.php?pedido='.$orderId);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$items=cart_items_for_user($db,$userId);$subtotal=array_reduce($items,static fn(float $sum,array $item):float=>$sum+(float)$item['precio']*(int)$item['cantidad'],0.);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/home.css"><link rel="stylesheet" href="assets/css/cart.css"></head><body><?=sideb_public_header('tienda')?><main class="cart-page container"><h1>Finalizar compra.</h1><?php if($error):?><p class="editorial-feedback" role="alert"><?=e($error)?></p><?php endif;?><?php if(!$items):?><p>Tu carrito está vacío. <a href="tienda.php">Ir a la tienda</a></p><?php else:?><div class="cart-layout"><form class="checkout-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><h2>Envío</h2><?php if($addresses):?><div class="form-field"><label for="address_id">Dirección guardada</label><select id="address_id" name="address_id"><option value="">Usar otra dirección</option><?php foreach($addresses as $address):?><option value="<?=(int)$address['id_direccion']?>" <?=$address['es_principal']?'selected':''?>><?=e($address['etiqueta'].' · '.$address['direccion'])?></option><?php endforeach;?></select></div><?php endif;?><div class="form-field"><label for="new_address">Otra dirección de envío</label><textarea id="new_address" name="new_address" maxlength="255" placeholder="Solo si no usarás una dirección guardada"></textarea></div><p>Puedes administrar tus direcciones desde <a href="perfil.php">Mi perfil</a>.</p><button class="button button-primary">Continuar con PayPal →</button></form><aside class="cart-summary"><h2>Resumen</h2><?php foreach($items as $item):?><div class="summary-line"><span><?=e($item['nombre'])?> × <?=(int)$item['cantidad']?></span><span><?=cart_money((float)$item['precio']*(int)$item['cantidad'])?></span></div><?php endforeach;?><div class="summary-line"><span>Envío</span><span>$99.00</span></div><div class="summary-line summary-total"><span>Total</span><span><?=cart_money($subtotal+99)?></span></div></aside></div><?php endif;?></main><?=sideb_footer()?></body></html>
